import{_ as t,H as a,f as i,i as E}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"13 | 变更场景（三）：连续绊倒两个云厂商的故障","description":"","frontmatter":{},"headers":[{"level":2,"title":"故障回顾","slug":"故障回顾","link":"#故障回顾","children":[]},{"level":2,"title":"案例解析","slug":"案例解析","link":"#案例解析","children":[{"level":3,"title":"原因解析","slug":"原因解析","link":"#原因解析","children":[]},{"level":3,"title":"问题解析","slug":"问题解析","link":"#问题解析","children":[]}]},{"level":2,"title":"优化措施","slug":"优化措施","link":"#优化措施","children":[{"level":3,"title":"预防数据格式错误","slug":"预防数据格式错误","link":"#预防数据格式错误","children":[]},{"level":3,"title":"控制上线影响","slug":"控制上线影响","link":"#控制上线影响","children":[]},{"level":3,"title":"提升恢复速度","slug":"提升恢复速度","link":"#提升恢复速度","children":[]}]},{"level":2,"title":"值得学习的地方","slug":"值得学习的地方","link":"#值得学习的地方","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"SRE实践：服务可靠性案例课/13｜变更场景（三）：连续绊倒两个云厂商的故障.md","filePath":"SRE实践：服务可靠性案例课/13｜变更场景（三）：连续绊倒两个云厂商的故障.md","lastUpdated":1795534831000}'),l={name:"SRE实践：服务可靠性案例课/13｜变更场景（三）：连续绊倒两个云厂商的故障.md"};function n(s,e,r,A,h,o){return a(),i("div",null,[...e[0]||(e[0]=[E('<h1 id="_13-变更场景-三-连续绊倒两个云厂商的故障" tabindex="-1">13 | 变更场景（三）：连续绊倒两个云厂商的故障 <a class="header-anchor" href="#_13-变更场景-三-连续绊倒两个云厂商的故障" aria-label="Permalink to &quot;13 | 变更场景（三）：连续绊倒两个云厂商的故障&quot;">​</a></h1><p>你好，我是白园。接下来我们进入变更的第三个场景——程序和数据类型的变更。今天我就来给你分享一种非常有意思的故障，这种故障连续绊倒了两个云厂商。</p><h2 id="故障回顾" tabindex="-1">故障回顾 <a class="header-anchor" href="#故障回顾" aria-label="Permalink to &quot;故障回顾&quot;">​</a></h2><p>2024 年 4 月 8 日，某云团队收到告警信息，云 API 服务处于异常状态。随即在某云工单、售后服务群以及微博等渠道开始大量出现某云控制台登录不上的客户反馈。经过故障定位发现，客户登录不上控制台是由于云 API 异常导致的。云 API 是云上统一的开放接口集合，客户可以通过 API 以编程方式管理和操控云端资源。</p><p>故障发生后，依赖云 API 提供产品能力的部分公有云服务，也因为云 API 的异常出现了无法使用的情况，比如云函数、文字识别、微服务平台、音频内容安全、验证码等。此次故障一共持续了近 87 分钟，期间共有 1957 个客户报障。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/1.png" alt=""></a></p><p>同样的事情也发生在另一家云上，不过是在 2023 年，云产品控制台访问及管控 API 调用出现异常。原因代码的逻辑缺陷，生成了一份不完整的白名单，进而影响了整个云 API 服务。</p><h2 id="案例解析" tabindex="-1">案例解析 <a class="header-anchor" href="#案例解析" aria-label="Permalink to &quot;案例解析&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/2.png" alt=""></a></p><h3 id="原因解析" tabindex="-1">原因解析 <a class="header-anchor" href="#原因解析" aria-label="Permalink to &quot;原因解析&quot;">​</a></h3><p>故障的原因是云 API 服务新版本向前兼容性考虑不够，以及配置数据灰度机制不足的问题。本次 API 升级过程中，由于新版本的接口协议发生了变化，在后台发布新版本之后对于旧版本前端传来的数据处理逻辑异常，导致生成了一条错误的配置数据，由于灰度机制不足导致异常数据快速扩散到了全网地域，造成整体 API 使用异常。</p><p>重启 API 后台服务，但此时因为承载 API 服务的容器平台也依赖 API 服务才能提供调度能力，即发生了循环依赖，导致服务无法自动拉起。只能通过运维手工启动方式才能使 API 服务重启成功，完成整个服务恢复。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/3.png" alt=""></a></p><p>从客户的视角来看，云服务大致可以分为数据面和控制面，数据面承载客户自身的业务，控制面负责操作云上不同产品。比如目前使用最广泛的 IaaS 服务基本上都是以直接面向数据面为主，控制面仅在客户购买或需要对资源层面进行调整操作时会用。此次发生的故障就在控制面。通俗来讲，如果把云服务类比为酒店，控制台相当于酒店的前台，是一个统一的服务入口。一旦酒店前台发生故障，会导致入住、续住等管理能力不可用，但已入住的客房不受影响。</p><h3 id="问题解析" tabindex="-1">问题解析 <a class="header-anchor" href="#问题解析" aria-label="Permalink to &quot;问题解析&quot;">​</a></h3><ul><li><p>检查机制的缺失：在全面推广前，似乎未进行充分的检查工作。从故障发生的角度来看，数据格式的错误是首要问题。在发现错误后，似乎没有检查和灰度测试的步骤，而是直接将数据推送到了生产环境。在数据上线前，缺乏必要的审核和分阶段部署机制，未经筛选的数据被直接全面推送，这影响了所有用户。</p></li><li><p>数据隔离策略的不足：尽管服务层面采取了隔离措施，但在数据层面，却未能实施有效的隔离策略。这使得数据被错误地广泛传播。</p></li><li><p>循环依赖问题：存在一个循环依赖的设计缺陷，其中预案和服务相互依赖。当 API 服务发生故障时，这种依赖关系阻碍了预案的及时启动。</p></li><li><p>升级与回滚问题：在最近的升级中，API 版本和配置数据都进行了更新。然而，在发生故障的时候，回滚操作只会滚了服务版本，没有在第一时间回归配置数据。</p></li></ul><h2 id="优化措施" tabindex="-1">优化措施 <a class="header-anchor" href="#优化措施" aria-label="Permalink to &quot;优化措施&quot;">​</a></h2><p>我们应该从三个关键方面进行考量：首先，探讨是否有可能预防问题的发生，以及预防的具体方法；其次，评估是否能够加快处理流程，并探索可能的加速手段；最后，想想还有哪些其他方面存在优化空间。</p><h3 id="预防数据格式错误" tabindex="-1">预防数据格式错误 <a class="header-anchor" href="#预防数据格式错误" aria-label="Permalink to &quot;预防数据格式错误&quot;">​</a></h3><p>深入探究数据格式错误的根本原因，特别是程序缺陷，并针对性地增强程序健壮性，以彻底解决问题。建立一套严密的数据校验体系，以确保所有数据在推送至生产环境前都经过了全面的审查。重点检查数据格式是否与现实标准相匹配。只有通过这一校验的数据才能继续进入后续流程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/4.png" alt=""></a></p><h3 id="控制上线影响" tabindex="-1">控制上线影响 <a class="header-anchor" href="#控制上线影响" aria-label="Permalink to &quot;控制上线影响&quot;">​</a></h3><p>采用分阶段的灰度发布方法，逐步引入新功能或配置更改。这一策略旨在通过在有限的用户群体中先行部署，快速识别潜在问题，并在必要时迅速执行回滚操作。例如，可以增设一个模拟线上环境进行详尽的测试和验证。这不仅有助于在早期发现并解决线上问题，同时也能提前识别线上环境中可能出现的故障。</p><p>这个案例里的回滚策略不够明确，初期仅对程序进行了回滚，忽略了配置数据的同步回滚，从而加剧了问题的扩散。更为妥当的做法是同步回滚程序和配置数据，确保系统恢复到一个已知的稳定状态，而不是单一地选择回滚程序。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/5.png" alt=""></a></p><p>我建议采用分阶段、区域化的方法更新。先在选定的试点地区（如北京）引入新功能或进行更新。然后，监控一段时间，验证新功能或新版本的稳定性。一旦确认试点地区的更新无误，再逐步将更新推广至其他地区的集群，最终实现全面部署。这种策略有助于控制更新风险，防止所有地区同时爆发。</p><p>我们可以部署一个自动化的异常检测与熔断机制，以实现对系统异常的即时响应。该机制能够在识别到任何异常时，迅速采取行动，中断当前的变更流程。例如，如果在区域 1 发现问题，该系统将自动触发暂停部署的措施，有效遏制问题蔓延至其他区域。</p><h3 id="提升恢复速度" tabindex="-1">提升恢复速度 <a class="header-anchor" href="#提升恢复速度" aria-label="Permalink to &quot;提升恢复速度&quot;">​</a></h3><p>首先，我们需要评估故障发生后的响应时间。例如，在一次故障中，定位问题耗时 23 分钟。在问题出现时，虽然立即执行了程序回滚，但配置数据没有一并回滚，这导致初步恢复措施没能奏效。如果程序和配置都已经更新，就必须同时进行回滚，确保系统恢复到稳定状态。所以，定期进行变更策略的模拟演练至关重要，这有助于确保在真实故障发生时，团队能够迅速启动恢复流程，将服务中断时间降到最低。</p><p>在配置和程序需要同时更新的情况下，应避免同时进行变更。我建议先完成一项变更，再进行下一项，确保过程清晰、可控。</p><p>简化 API 服务中的预案，减少 API 间的循环依赖，从而增强各服务单元的独立性并提升整体系统的稳定性。这样，在遇到问题时，可以确保系统能够安全地执行回滚操作。此外，还需要为 API 服务设计并实施逃生通道机制，确保在系统故障发生时，能够迅速切换至备用路径。</p><h2 id="值得学习的地方" tabindex="-1">值得学习的地方 <a class="header-anchor" href="#值得学习的地方" aria-label="Permalink to &quot;值得学习的地方&quot;">​</a></h2><p>他们在对外公告方面的表现值得称赞，不仅提供了详尽的事件细节，还对各种情况给出了清晰的解释，从而获得了公众的广泛好评。在故障通知中，明确指出了受影响的业务范围、故障的根本原因以及预计的修复时间，保持信息的透明度和及时性，这一点也得到了大家认可。</p><p>故障处理流程也有值得学习的地方，在复盘的文章中给出了每一步的思考和决策，目前来看没有大的失误。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课我们重点分析了数据变更中需要关注的点，同时我把别人做得好的地方和不好的地方整理了一个表格供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/13/6.png" alt=""></a></p><p>至关重要的一点是，我们必须认真吸取他人的经验教训。对此问题应持有严肃认真的态度，避免任何冷漠或嘲讽的情绪。面对类似事件时，我们应积极思考如何进行改进和优化。回顾去年，某云服务在遭遇另一云服务提供商的故障时，似乎未能吸取教训或采取必要的整改措施，结果导致自身服务也出现了问题。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>假如你需要进行配置变更、代码发布、数据更新，那么你的执行顺序是什么？另外你平时有学习别人的案例吗，说说如何把别人的经验应用到自己的业务上。欢迎你把你的答案分享到评论区，也欢迎你把这节课的内容分享给其他朋友，我们下节课再见！</p>',40)])])}const g=t(l,[["render",n]]);export{c as __pageData,g as default};
